#[test]
fn workflow_trace_reports_and_source_bound_production_roundtrip_without_status_repair() {
    let request = request(); let handle = SolveHandle::new();
    let options = SolveOptions { cancellation_handle: Some(&handle), ..Default::default() };
    for reason in [TerminationReason::Completed, TerminationReason::TimeLimit, TerminationReason::Cancelled, TerminationReason::BackendFailure] {
        let text = execute(&request.model, request.csp1d_options.clone().unwrap(), Arc::new(Fake(move |model: &LinearTriadModel, _: &SolveOptions<'_>| report(model, reason))), &options).unwrap();
        let decoded = decode_csp1d_execution_report(&text, &request.model).unwrap();
        assert_eq!(decoded.summary.stage_count, 1); assert!(!decoded.summary.candidate_complete);
        assert_eq!(decoded.summary.business_status, if reason == TerminationReason::Completed { Csp1dBusinessStatus::Feasible } else { Csp1dBusinessStatus::Failed });
        assert_eq!(decoded.production.is_some(), reason == TerminationReason::Completed);
        assert_eq!(decoded.summary.stop, match reason { TerminationReason::Cancelled => Csp1dExecutionStop::Cancelled,
            TerminationReason::TimeLimit => Csp1dExecutionStop::TimeLimit, _ => Csp1dExecutionStop::Completed });
        for variant in 0..6 {
            let mut forged: Csp1dExecutionReportArtifact = serde_json::from_str(&text).unwrap();
            match variant {
                0 => forged.source_fingerprint = "foreign".into(),
                1 => forged.business_status = if decoded.production.is_some() { Csp1dBusinessStatus::Failed } else { Csp1dBusinessStatus::Feasible },
                2 => { forged.plans.pop(); },
                3 => forged.stages.push(forged.stages[0].clone()),
                4 => { let mut trace: serde_json::Value = serde_json::from_str(&forged.trace_json).unwrap(); trace["final_plan_count"] = 100.into(); forged.trace_json = serde_json::to_string(&trace).unwrap(); },
                _ => forged.schema_version = "2.0".into(),
            }
            assert!(decode_csp1d_execution_report(&serde_json::to_string(&forged).unwrap(), &request.model).is_err(), "{reason:?} variant {variant}");
        }
    }
}

#[test]
fn no_initial_columns_precancellation_and_backend_errors_never_fabricate_production() {
    let request = request();
    for cancel in [false, true] {
        let handle = SolveHandle::new(); if cancel { handle.cancel(CancellationOrigin::External); }
        let solver = Arc::new(Fake(|_: &LinearTriadModel, _: &SolveOptions<'_>| -> ospf_rust_core::Result<SolveReport<f64>> { panic!("no columns must not invoke a backend") }));
        let mut source = crate::csp1d::decode_csp1d_problem(&request.model).unwrap().0;
        source.products[0].width[0].value = 300.0;
        let source = encode_csp1d_problem(source).unwrap();
        let text = execute(&source, request.csp1d_options.clone().unwrap(), solver, &SolveOptions { cancellation_handle: Some(&handle), ..Default::default() }).unwrap();
        let result = decode_csp1d_execution_report(&text, &source).unwrap();
        assert_eq!(result.summary.business_status, Csp1dBusinessStatus::NoInitialPlans); assert_eq!(result.summary.stage_count, 0);
        assert_eq!(result.summary.stop, if cancel { Csp1dExecutionStop::Cancelled } else { Csp1dExecutionStop::Completed }); assert!(result.production.is_none());
    }
    let handle = SolveHandle::new();
    let text = execute(&request.model, request.csp1d_options.clone().unwrap(), Arc::new(Fake(|_: &LinearTriadModel, _: &SolveOptions<'_>| {
        Err(ospf_rust_core::SolverError::NotAvailable("test runtime unavailable".into()).into())
    })), &SolveOptions { cancellation_handle: Some(&handle), ..Default::default() }).unwrap();
    let result = decode_csp1d_execution_report(&text, &request.model).unwrap();
    assert_eq!(result.summary.business_status, Csp1dBusinessStatus::Failed); assert!(result.production.is_none()); assert!(result.artifact.trace_json.contains("test runtime unavailable"));
}

#[test]
fn worker_cancellation_race_retains_real_report_and_job_capacity() {
    for cancel in [false, true] {
        let request = request(); let source = request.model.clone(); let configuration = request.csp1d_options.clone().unwrap();
        let engine = NativeEngine::new(1);
        let (entered, ready) = sync_channel(1); let (finish, gate) = sync_channel(1); let gate = Mutex::new(gate);
        let fake = Arc::new(Fake(move |model: &LinearTriadModel, options: &SolveOptions<'_>| {
            entered.send(()).unwrap(); gate.lock().unwrap().recv_timeout(Duration::from_secs(5)).unwrap();
            report(model, if options.cancellation_handle.unwrap().is_cancelled() { TerminationReason::Cancelled } else { TerminationReason::Completed })
        }));
        let job = engine.start_encoded(request.clone(), move |options| execute(&source, configuration, fake, options)).unwrap();
        ready.recv_timeout(Duration::from_secs(5)).unwrap();
        assert_eq!(engine.release(&job.id).unwrap_err().code, "Busy"); assert_eq!(engine.submit(request.clone()).unwrap_err().code, "Busy");
        if cancel { engine.cancel(&job.id).unwrap(); } finish.send(()).unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        let view = loop { let view = engine.get(&job.id).unwrap(); if view.status != JobStatus::Running { break view; }
            assert!(Instant::now() < deadline); std::thread::sleep(Duration::from_millis(1)); };
        assert_eq!(view.status, JobStatus::Completed, "{:?}", view.error);
        let decoded = decode_csp1d_execution_report(view.report_json.as_ref().unwrap(), &request.model).unwrap();
        assert_eq!(decoded.summary.stop, if cancel { Csp1dExecutionStop::Cancelled } else { Csp1dExecutionStop::Completed });
        assert_eq!(decoded.production.is_some(), !cancel);
        assert_eq!(engine.cancel(&job.id).unwrap().report_json, view.report_json); engine.release(&job.id).unwrap();
    }
}
